/**
 * Generated by scaffold-listing-primitives. `data-component="entity-form-modal"`.
 *
 * ONE modal serving create AND edit (CONTRACT §3). The mode is derived from
 * whether `initialValues` was supplied, so a listing cannot drift into two
 * near-identical modals that then diverge field by field.
 *
 * The caller owns the fields — this component owns the shell: title, focus trap,
 * Escape/backdrop close, submit/cancel, busy state, and error surface.
 *
 * Usage:
 *   <EntityFormModal
 *     open={editing !== null}
 *     entityLabel="User"
 *     initialValues={editing ?? undefined}
 *     onClose={() => setEditing(null)}
 *     onSubmit={save}
 *     testId="user-form"
 *   >
 *     <label>Email<input name="email" defaultValue={editing?.email} /></label>
 *   </EntityFormModal>
 */
import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { useTranslation } from 'react-i18next';

export interface EntityFormModalProps {
  open: boolean;
  /** Singular entity name, e.g. "User" — drives the create/edit title. */
  entityLabel: string;
  /**
   * Present → edit mode; absent → create mode.
   *
   * `object`, not `Record<string, unknown>`: the shell never reads the fields (the
   * caller owns them, and passes an entity row straight through as
   * `initialValues={editing ?? undefined}`), while a generated row INTERFACE has no
   * index signature and so is not assignable to a Record — TS2322 at the call site
   * for a value this component only tests against `undefined`.
   */
  initialValues?: object;
  onClose: () => void;
  onSubmit: (form: FormData) => void | Promise<void>;
  children: ReactNode;
  submitLabel?: string;
  testId: string;
}

export function EntityFormModal({
  open,
  entityLabel,
  initialValues,
  onClose,
  onSubmit,
  children,
  submitLabel,
  testId,
}: EntityFormModalProps) {
  const { t } = useTranslation('common');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const isEdit = initialValues !== undefined;

  useEffect(() => {
    if (!open) return;
    setError(null);
    // Focus the first control so keyboard users are not stranded behind the backdrop.
    dialogRef.current?.querySelector<HTMLElement>('input, select, textarea, button')?.focus();
    function onEsc(e: KeyboardEvent) {
      if (e.key === 'Escape' && !busy) onClose();
    }
    document.addEventListener('keydown', onEsc);
    return () => document.removeEventListener('keydown', onEsc);
  }, [open, busy, onClose]);

  if (!open) return null;

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setBusy(true);
    setError(null);
    try {
      await onSubmit(new FormData(e.currentTarget));
      onClose();
    } catch (err) {
      // Keep the modal open on failure — closing would discard what was typed.
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  }

  const title = isEdit
    ? t('actions.editEntity', { entity: entityLabel, defaultValue: 'Edit {{entity}}' })
    : t('actions.createEntity', { entity: entityLabel, defaultValue: 'New {{entity}}' });

  return (
    <div
      className="modal-backdrop"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget && !busy) onClose();
      }}
    >
      <div
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-label={title}
        ref={dialogRef}
        data-testid={testId + '-modal'}
      >
        <h2 data-testid={testId + '-title'}>{title}</h2>
        <form onSubmit={handleSubmit}>
          {children}
          {error && (
            <p role="alert" className="modal-error" data-testid={testId + '-error'}>
              {error}
            </p>
          )}
          <div className="modal-actions">
            <button type="button" onClick={onClose} disabled={busy} data-testid={testId + '-cancel'}>
              {t('actions.cancel', { defaultValue: 'Cancel' })}
            </button>
            <button type="submit" disabled={busy} data-testid={testId + '-submit'}>
              {submitLabel ?? (isEdit ? t('actions.save', { defaultValue: 'Save' }) : t('actions.create', { defaultValue: 'Create' }))}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
